      "summary": "首页 > 科研进展 恒星大多成团形成。银河系盘上的疏散星团在长期演化中受到银河系潮汐力作用，逐渐瓦解并把成员恒星释放到银河系盘中。中子星作为大质量恒星演化的遗骸，也起源于星团。目前，在银河系盘上已发现数千颗表现为脉冲星的中子星，但此前天文学家从未直接观测到中子星从诞生星团进入银河系盘，导致银盘上中子星族群的演化起源环节",
