      "title": "DeepSeek招150人，全部押注工程岗",
      "summary": "9月8日，DeepSeek启动新一轮招聘，计划招募约150名工程师，仅设服务端开发、Agent弹性计算研发两类工程岗，面向2至10年经验的资深后端工程师，无AI研究类岗位。这是其两个多月内第二次大规模扩招，不同于6月覆盖7大类33个岗位的全面扩招，此次精准押注工程化与基础设施，折射出这家大模型公司将竞争重心从模型研究转",
